final class ProductionTasksExperience
{
    private const ROUTE='/production/tasks';
    public static function handles(string $route):bool{return $route===self::ROUTE;}

    public static function render(string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user||!AccessPolicy::canManageProduction($user))self::forbidden();$_SESSION['production_tasks_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$user,$basePath);
        $data=ProductionReadinessService::build($db,$user);self::page($basePath,$user,$data);
    }

    private static function handlePost(PDO $db,array $user,string $basePath):never
    {
        if(!hash_equals((string)($_SESSION['production_tasks_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session expired.');self::redirect($basePath.self::ROUTE);}
        try{$action=(string)($_POST['action']??'');$productionId=(int)($_POST['production_id']??0);if($action==='save'){ProductionReadinessService::saveChecklistItem($db,$user,$productionId,$_POST);self::flash('success','Checklist item saved.');}elseif($action==='set_volunteer_leads'){
            $selected=ProductionContext::selected($db,$user);
            if(!$selected||(int)$selected['id']!==$productionId)throw new RuntimeException('Choose the current Working Production.');
            $ids=array_values(array_unique(array_map('intval',(array)($_POST['lead_user_ids']??[]))));
            $candidates=$db->prepare("SELECT DISTINCT u.id FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status='active' WHERE pm.production_id=:p AND pm.status='active' AND pm.audience_type IN ('staff','guardian')");
            $candidates->execute(['p'=>$productionId]);$eligible=array_map('intval',$candidates->fetchAll(PDO::FETCH_COLUMN));
            foreach($ids as $id)if(!in_array($id,$eligible,true))throw new RuntimeException('Volunteer Leads must be active adult production members.');
            $db->beginTransaction();
            try{$db->prepare("DELETE FROM production_volunteer_leads WHERE production_id=:p")->execute(['p'=>$productionId]);
            $insert=$db->prepare("INSERT INTO production_volunteer_leads (production_id,user_id,appointed_by_user_id) VALUES (:p,:user,:actor)");
            foreach($ids as $id)$insert->execute(['p'=>$productionId,'user'=>$id,'actor'=>(int)$user['id']]);
            $db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
            self::flash('success','Production Volunteer Leads updated.');
        }elseif($action==='toggle_done'){ProductionReadinessService::toggleDone($db,$user,$productionId,(int)($_POST['item_id']??0));self::flash('success','Checklist item updated.');}else throw new RuntimeException('Choose a valid readiness action.');}catch(RuntimeException $e){self::flash('error',$e->getMessage());}
        self::redirect($basePath.self::ROUTE);
    }

    private static function page(string $basePath,array $user,array $data):never
    {
        $production=$data['production']??null;$db=Database::connect(dirname(__DIR__));$taskGroups=$production?ScheduleAudience::groups($db,(int)$production['id']):[];$groupMembers=[];foreach($taskGroups as $taskGroup){$members=$db->prepare("SELECT DISTINCT pm.user_id FROM production_group_members pgm JOIN production_memberships pm ON pm.id=pgm.production_membership_id AND pm.status='active' JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status='active' WHERE pgm.group_id=:group_id AND pgm.status='active'");$members->execute(['group_id'=>(int)$taskGroup['id']]);$groupMembers[(int)$taskGroup['id']]=array_map('intval',$members->fetchAll(PDO::FETCH_COLUMN));}$u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=$_SESSION['production_tasks_flash']??null;unset($_SESSION['production_tasks_flash']);$production=$data['production']??null;header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Production tasks · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/production-readiness.css?v=20261025-compact-tasks')?>"><?php WorkspaceUI::operationsStyles($basePath); ?></head><body class="app-body ux-operations ux-workspace ux-operational ux-tasks"><a class="ux-skip" href="#ux-main">Skip to main content</a><div class="unified-shell"><?php AppNavigation::renderSidebar(self::ROUTE,$basePath,$user);?><main class="unified-main" id="ux-main" tabindex="-1"><?php AppNavigation::renderHeader('Production','Tasks',$basePath,AppNavigation::productionSubnav(self::ROUTE,$user));?><div class="pr-page ops-page"><?php if($flash):?><div class="pr-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?>
        <?php if(!$production):?><section class="pr-empty"><h2>Select an active Working Production first.</h2><p>Readiness is intentionally scoped to one production at a time.</p><a href="<?=$u('/production')?>">Choose production</a></section><?php else:$s=$data['summary'];?><section class="pr-hero"><div><small>WORKING PRODUCTION</small><h2><?=$e((string)$production['title'])?></h2><p><?=$e((string)($production['season']?:'Season not set'))?> · Assign and track production tasks for your team.</p></div><div class="pr-score"><b><?=$s['readiness_percent']===null?'—':(int)$s['readiness_percent'].'%'?></b><span><?=$s['readiness_percent']===null?'No checklist items yet':'checklist complete'?></span></div></section>
        <?php
        $leadCandidateQuery=$db->prepare("SELECT DISTINCT u.id,CONCAT(u.first_name,' ',u.last_name) name FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status='active' WHERE pm.production_id=:p AND pm.status='active' AND pm.audience_type IN ('staff','guardian') ORDER BY name");
        $leadCandidateQuery->execute(['p'=>(int)$production['id']]);$leadCandidates=$leadCandidateQuery->fetchAll();
        $leadIds=[];$leadsAvailable=true;
        try{$leadQuery=$db->prepare("SELECT user_id FROM production_volunteer_leads WHERE production_id=:p");$leadQuery->execute(['p'=>(int)$production['id']]);$leadIds=array_map('intval',$leadQuery->fetchAll(PDO::FETCH_COLUMN));}
        catch(PDOException $exception){
            if($exception->getCode()!=='42S02')throw $exception;
            $leadsAvailable=false;
            error_log('CTSMD Tasks: production_volunteer_leads table missing; apply migration 082_production_volunteer_leads.sql');
        }
        ?>
        <?php if(!$leadsAvailable):?><div class="pr-flash error" role="alert">Volunteer Leads setup is pending a database migration. Other Tasks features remain available.</div><?php else:?><div style="display:flex;justify-content:flex-end;margin:8px 0 16px"><button type="button" class="button" data-open-leads>Manage Volunteer Leads</button></div>
        <div class="pr-lead-backdrop" data-close-leads hidden></div><aside class="pr-task-drawer" data-leads-drawer hidden tabindex="-1" role="dialog" aria-modal="true" aria-label="Manage Volunteer Leads"><header><div><small>PRODUCTION RESPONSIBILITIES</small><h2>Volunteer Leads</h2></div><button type="button" data-close-leads aria-label="Close Volunteer Leads">×</button></header>
        <p>Designate trusted adult production members to coordinate volunteers and own tasks. This does not grant administrative access.</p>
        <form method="post" class="pr-task-form ops-form"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['production_tasks_csrf'])?>"><input type="hidden" name="production_id" value="<?=(int)$production['id']?>"><input type="hidden" name="action" value="set_volunteer_leads"><fieldset class="pr-multi-assignees"><legend>Designated leads</legend><?php foreach($leadCandidates as $lead):?><label><input type="checkbox" name="lead_user_ids[]" value="<?=(int)$lead['id']?>"<?=in_array((int)$lead['id'],$leadIds,true)?' checked':''?>><span><?=$e((string)$lead['name'])?></span></label><?php endforeach;?></fieldset><button type="submit">Save Volunteer Leads</button></form></aside>
        <?php endif;?><script>(function(){const panel=document.querySelector('[data-leads-drawer]'),back=document.querySelector('.pr-lead-backdrop');if(!panel||!back)return;document.addEventListener('click',e=>{if(e.target.closest('[data-open-leads]')){panel.hidden=false;back.hidden=false;panel.focus();}if(e.target.closest('[data-close-leads]')){panel.hidden=true;back.hidden=true;}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){panel.hidden=true;back.hidden=true;}});})();</script>
        <style>.pr-lead-backdrop{position:fixed;inset:0;background:#13121a80;z-index:1250}[data-leads-drawer]{z-index:1251}</style>
        <section class="pr-section"><header><div><small>PRODUCTION CHECKLIST</small><h3>What your team still needs to do</h3></div></header><div class="pr-layout"><div class="pr-list"><?php if(!$data['checklist']):?><div class="pr-empty-card">No checklist items yet. Add the practical production work Connect cannot infer on its own.</div><?php endif;?><?php foreach($data['checklist'] as $item):
 $overdue=$item['status']!=='done'&&!empty($item['due_at'])&&strtotime($item['due_at'])<time();
 $personAssignments=ProductionChecklistAssignmentService::forItem($db,(int)$production['id'],(int)$item['id']);
 $completedCount=count(array_filter($personAssignments,static fn(array $assignment):bool=>!empty($assignment['completed_at'])));
?><article class="pr-item pr-item-compact <?=$e((string)$item['status'])?><?=$overdue?' overdue':''?>">
 <form method="post" class="pr-check"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['production_tasks_csrf'])?>"><input type="hidden" name="production_id" value="<?=(int)$production['id']?>"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><input type="hidden" name="action" value="toggle_done"><button type="submit" aria-label="<?=$item['status']==='done'?'Reopen':'Complete'?> checklist item"><?=$item['status']==='done'?'✓':'○'?></button></form>
 <details class="pr-item-details">
  <summary><span class="pr-item-heading"><small><?=$e(strtoupper((string)$item['category']))?><?=$overdue?' · OVERDUE':''?></small><strong><?=$e((string)$item['title'])?></strong><span class="pr-item-meta"><?=$item['assignee']?'Owner: '.$e((string)$item['assignee']).' · ':''?><?=$item['due_at']?'Due '.$e(date('M j, g:i A',strtotime((string)$item['due_at']))).' · ':''?><?=ucwords(str_replace('_',' ',$e((string)$item['status'])))?></span></span><span class="pr-item-progress"><?=count($personAssignments) ? $completedCount.'/'.count($personAssignments).' complete':'No assignees'?></span><span class="pr-item-chevron" aria-hidden="true">⌄</span></summary>
  <div class="pr-item-expanded">
