   <button type="button" class="pr-assignment-open" data-open-task="<?=(int)$item['id']?>" aria-label="Manage assignments for <?=$e((string)$item['title'])?>">Manage assignments <span aria-hidden="true">›</span></button>
  </div>
 </details>
</article><?php endforeach;?></div><aside class="pr-composer"><small>ADD CHECKLIST ITEM</small><h3>Track a production task</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['production_tasks_csrf'])?>"><input type="hidden" name="production_id" value="<?=(int)$production['id']?>"><input type="hidden" name="action" value="save"><label>Task<input name="title" maxlength="190" required placeholder="Confirm photographer"></label><label>Category<input name="category" maxlength="100" required value="General"></label><input type="hidden" name="assignment_enabled" value="1"><fieldset class="pr-group-picker"><legend>Select production groups</legend><p>Select a group to check all its active members, then adjust individuals below.</p><div class="pr-group-list"><?php foreach($taskGroups as $taskGroup):?><label><input type="checkbox" data-task-group="<?=(int)$taskGroup['id']?>" data-group-members="<?=$e(implode(',',($groupMembers[(int)$taskGroup['id']]??[])))?>"><span><?=$e((string)$taskGroup['name'])?> <small>(<?=(int)$taskGroup['member_count']?>)</small></span></label><?php endforeach;?></div></fieldset><fieldset class="pr-multi-assignees"><legend>Assign to students and/or parents</legend><?php foreach(ProductionChecklistAssignmentService::candidates($db,(int)$production['id']) as $candidate):?><label><input type="checkbox" name="assignee_ids[]" value="<?=(int)$candidate['id']?>"><span><?=$e((string)$candidate['name'])?> · <?=$e(ucfirst((string)$candidate['audience_type']))?></span></label><?php endforeach;?></fieldset><label class="pr-required"><input type="checkbox" name="required_each" value="1" checked> Required for each assigned person</label><label>Owner<select name="assigned_to_user_id"><option value="">Unassigned</option><?php foreach($data['staff'] as $staff):?><option value="<?=(int)$staff['id']?>"><?=$e((string)$staff['name'])?> · <?=$e((string)($staff['owner_role']??'Staff'))?></option><?php endforeach;?></select></label><label>Due<input type="datetime-local" name="due_at"></label><label>Status<select name="status"><option value="open">Open</option><option value="in_progress">In progress</option><option value="blocked">Blocked</option><option value="done">Done</option></select></label><label>Notes<textarea name="notes" maxlength="1000" rows="4"></textarea></label><button type="submit">Add checklist item</button></form></aside></div></section>
        <div class="pr-task-backdrop" data-close-task hidden></div>
