        <script>(function(){const backdrop=document.querySelector('.pr-task-backdrop');let current=null,previous=null;function close(){if(!current)return;current.hidden=true;current=null;backdrop.hidden=true;document.body.style.overflow='';previous?.focus?.();}function open(el){close();previous=document.activeElement;current=el;current.hidden=false;backdrop.hidden=false;document.body.style.overflow='hidden';current.focus();}document.addEventListener('click',function(event){const button=event.target.closest('[data-open-task]');if(button){open(document.querySelector('[data-task-drawer="'+button.dataset.openTask+'"]'));return;}if(event.target.closest('[data-close-task]'))close();});document.addEventListener('keydown',function(event){if(event.key==='Escape')close();if(event.key!=='Tab'||!current)return;const controls=[...current.querySelectorAll('button:not([disabled]),input:not([disabled])')].filter(x=>x.offsetParent!==null);if(!controls.length)return;if(event.shiftKey&&document.activeElement===controls[0]){event.preventDefault();controls[controls.length-1].focus();}else if(!event.shiftKey&&document.activeElement===controls[controls.length-1]){event.preventDefault();controls[0].focus();}});})();</script>
